import{_ as e,o as c,c as o,a5 as d}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"04 — Gói Truyền thông, Chiến dịch & Yêu cầu Nội dung (Media Package, Media Campaign & Content Request)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/04-media-package-campaign.md","filePath":"ba/04-media-package-campaign.md"}'),n={name:"ba/04-media-package-campaign.md"};function a(i,t,g,l,h,r){return c(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="_04-—-goi-truyen-thong-chien-dich-yeu-cau-noi-dung-media-package-media-campaign-content-request" tabindex="-1">04 — Gói Truyền thông, Chiến dịch &amp; Yêu cầu Nội dung (Media Package, Media Campaign &amp; Content Request) <a class="header-anchor" href="#_04-—-goi-truyen-thong-chien-dich-yeu-cau-noi-dung-media-package-media-campaign-content-request" aria-label="Permalink to &quot;04 — Gói Truyền thông, Chiến dịch &amp; Yêu cầu Nội dung (Media Package, Media Campaign &amp; Content Request)&quot;">​</a></h1><p>&gt; [&lt;&lt; 03 - Agency &amp; Workspace](file:///D:/ProjectCode/BrandHub/brandhub-infrastructure/docs/ba/03-agency-workspace-management.md) | [Overview](file:///D:/ProjectCode/BrandHub/brandhub-infrastructure/docs/ba/00-overview.md) | [Tiếp: 05 - Content &amp; Task Workflow &gt;&gt;](file:///D:/ProjectCode/BrandHub/brandhub-infrastructure/docs/ba/05-content-task-workflow.md) &gt; &gt; <strong>Phạm vi FR chuẩn</strong>: <strong>Mục <code>3.5 Media Package &amp; Media Campaign</code> — 13 FR (<code>3.5.1</code> – <code>3.5.13</code>)</strong> | <code>UC-040</code> – <code>UC-052</code>. &gt; Đã đồng bộ với <strong>8 loại Dịch vụ / Công việc chuẩn (<code>PackageServiceType</code> ↔ <code>TaskType</code>)</strong>, luồng <code>Manager-led Package &amp; Campaign Approval</code>, và luồng <strong>Chiến dịch Cá nhân không cần Gói dịch vụ (<code>workspaceMode = &quot;PERSONAL&quot;</code>)</strong>.</p><hr><h2 id="_1-bang-tong-hop-13-yeu-cau-chuc-nang-chuan-3-5-1-–-3-5-13" tabindex="-1">1. Bảng Tổng hợp 13 Yêu cầu Chức năng Chuẩn (<code>3.5.1</code> – <code>3.5.13</code>) <a class="header-anchor" href="#_1-bang-tong-hop-13-yeu-cau-chuc-nang-chuan-3-5-1-–-3-5-13" aria-label="Permalink to &quot;1. Bảng Tổng hợp 13 Yêu cầu Chức năng Chuẩn (`3.5.1` – `3.5.13`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Mã FR</th><th style="text-align:center;">Mã UC</th><th style="text-align:left;">Tên Chức năng Chuẩn (Atomic CRUD FR)</th><th style="text-align:left;">Actors / Roles Chuẩn</th><th style="text-align:left;">Mô tả Nghiệp vụ Cốt lõi</th></tr></thead><tbody><tr><td style="text-align:center;"><strong><code>3.5.1</code></strong></td><td style="text-align:center;"><code>UC-040</code></td><td style="text-align:left;"><strong>Create Media Package</strong></td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:left;">Tạo mới hoặc tùy chỉnh Gói truyền thông mẫu (<code>MediaPackage</code>) ở cấp <code>Agency</code> với danh mục các hạng mục dịch vụ, số lượng, đơn vị chuẩn, đơn giá và điều khoản.</td></tr><tr><td style="text-align:center;"><strong><code>3.5.2</code></strong></td><td style="text-align:center;"><code>UC-041</code></td><td style="text-align:left;"><strong>View Template Media Package</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:left;">Xem danh sách và chi tiết các Gói truyền thông mẫu của <code>Agency</code> hoặc bảng đề xuất gói gắn với <code>Workspace</code> (hỗ trợ xuất PDF đề xuất đa ngôn ngữ &amp; chia sẻ link công khai cho <code>Guest</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.5.3</code></strong></td><td style="text-align:center;"><code>UC-042</code></td><td style="text-align:left;"><strong>Request Media Package</strong></td><td style="text-align:left;"><code>Manager</code>, <code>Client</code></td><td style="text-align:left;">Chọn hoặc đề xuất áp dụng một Gói truyền thông cho <code>Workspace</code> (<code>WorkspaceMediaPackage</code>), tùy chỉnh hạng mục/số lượng theo nhu cầu dự án.</td></tr><tr><td style="text-align:center;"><strong><code>3.5.4</code></strong></td><td style="text-align:center;"><code>UC-043</code></td><td style="text-align:left;"><strong>Approve Media Package</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:left;">Xác nhận chốt Gói truyền thông cho <code>Workspace</code> (<code>status = APPROVED</code>) để mở khóa bước lập Chiến dịch truyền thông trong chế độ <code>AGENCY</code>.</td></tr><tr><td style="text-align:center;"><strong><code>3.5.5</code></strong></td><td style="text-align:center;"><code>UC-044</code></td><td style="text-align:left;"><strong>Create Media Campaign</strong></td><td style="text-align:left;"><code>Manager</code></td><td style="text-align:left;">Khởi tạo Kế hoạch Chiến dịch truyền thông (<code>MediaCampaign</code>): đặt tên, mục tiêu, thời gian bắt đầu/kết thúc, thông điệp chủ đạo và danh sách các hạng mục công việc (<code>workItems</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.5.6</code></strong></td><td style="text-align:center;"><code>UC-045</code></td><td style="text-align:left;"><strong>View Media Campaign</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Xem chi tiết kế hoạch chiến dịch, tiến độ tổng thể và <strong>Lịch trình Chiến dịch (<code>CampaignTimelineGrid</code>)</strong> kèm trạng thái từng Subtask, cờ trễ hạn và cờ chờ <code>Client</code> duyệt.</td></tr><tr><td style="text-align:center;"><strong><code>3.5.7</code></strong></td><td style="text-align:center;"><code>UC-046</code></td><td style="text-align:left;"><strong>Update Media Campaign</strong></td><td style="text-align:left;"><code>Manager</code></td><td style="text-align:left;">Cập nhật thông tin chiến dịch, điều chỉnh danh sách hạng mục công việc, thời hạn hoặc phân bổ lại nhân sự trong quá trình thực hiện.</td></tr><tr><td style="text-align:center;"><strong><code>3.5.8</code></strong></td><td style="text-align:center;"><code>UC-047</code></td><td style="text-align:left;"><strong>Approve Media Campaign</strong></td><td style="text-align:left;"><code>Manager</code>, <code>Client</code></td><td style="text-align:left;">Chốt kế hoạch chiến dịch và triển khai (<code>Deploy Campaign</code>): tự động sinh hàng loạt Công việc cha (<code>TaskDocument</code>) kèm đầy đủ bộ <strong>Subtask theo vai trò chuẩn (<code>TaskCatalog</code>)</strong>.</td></tr><tr><td style="text-align:center;"><strong><code>3.5.9</code></strong></td><td style="text-align:center;"><code>UC-048</code></td><td style="text-align:left;"><strong>Complete Media Campaign</strong></td><td style="text-align:left;"><code>Manager</code></td><td style="text-align:left;">Đánh dấu hoàn tất Chiến dịch truyền thông (<code>status = COMPLETED</code>) sau khi các hạng mục công việc cốt lõi đã hoàn thành và nghiệm thu.</td></tr><tr><td style="text-align:center;"><strong><code>3.5.10</code></strong></td><td style="text-align:center;"><code>UC-049</code></td><td style="text-align:left;"><strong>Create Content Request</strong></td><td style="text-align:left;"><code>Client</code></td><td style="text-align:left;">Khách hàng (<code>Client</code>) tạo Yêu cầu nội dung phát sinh (<code>ContentRequest</code>) từ <code>Client Portal</code> gửi cho đội ngũ <code>Workspace</code>.</td></tr><tr><td style="text-align:center;"><strong><code>3.5.11</code></strong></td><td style="text-align:center;"><code>UC-050</code></td><td style="text-align:left;"><strong>Track Request Status</strong></td><td style="text-align:left;"><code>Manager</code>, <code>Client</code></td><td style="text-align:left;">Theo dõi trạng thái xử lý của <code>ContentRequest</code> (<code>PENDING</code> → <code>APPROVED</code> / <code>IN_PROGRESS</code> / <code>COMPLETED</code> / <code>REJECTED</code> / <code>CANCELLED</code>) và công việc (<code>Task</code>) được sinh ra từ yêu cầu đó.</td></tr><tr><td style="text-align:center;"><strong><code>3.5.12</code></strong></td><td style="text-align:center;"><code>UC-051</code></td><td style="text-align:left;"><strong>Update Request</strong></td><td style="text-align:left;"><code>Manager</code>, <code>Client</code></td><td style="text-align:left;"><code>Client</code> chỉnh sửa nội dung yêu cầu khi còn ở trạng thái <code>PENDING</code>; <code>Manager</code> tiếp nhận, phản hồi, duyệt chuyển thành <code>Task</code> hoặc từ chối kèm lý do.</td></tr><tr><td style="text-align:center;"><strong><code>3.5.13</code></strong></td><td style="text-align:center;"><code>UC-052</code></td><td style="text-align:left;"><strong>Cancel Request</strong></td><td style="text-align:left;"><code>Client</code></td><td style="text-align:left;"><code>Client</code> hủy một <code>ContentRequest</code> do mình tạo khi yêu cầu đang ở trạng thái <code>PENDING</code> (chưa được <code>Manager</code> triển khai thành <code>Task</code>).</td></tr></tbody></table><hr><h2 id="_2-anh-xa-8-loai-hang-muc-dich-vu-packageservicetype-sang-8-loai-cong-viec-tasktype" tabindex="-1">2. Ánh xạ 8 Loại Hạng mục Dịch vụ (<code>PackageServiceType</code>) sang 8 Loại Công việc (<code>TaskType</code>) <a class="header-anchor" href="#_2-anh-xa-8-loai-hang-muc-dich-vu-packageservicetype-sang-8-loai-cong-viec-tasktype" aria-label="Permalink to &quot;2. Ánh xạ 8 Loại Hạng mục Dịch vụ (`PackageServiceType`) sang 8 Loại Công việc (`TaskType`)&quot;">​</a></h2><p>Hệ thống chuẩn hóa 8 loại dịch vụ truyền thông trong Gói dịch vụ (<code>PackageOfferingValidator</code> &amp; <code>CampaignPlanValidator</code>), ánh xạ 1-đối-1 sang 8 loại Công việc (<code>TaskType</code>) khi triển khai chiến dịch:</p><table tabindex="0"><thead><tr><th style="text-align:center;">STT</th><th style="text-align:left;"><code>PackageServiceType</code></th><th style="text-align:left;"><code>TaskType</code> sinh ra khi Deploy</th><th style="text-align:center;">Đơn vị chuẩn (<code>Standard Unit</code>)</th><th style="text-align:left;">Số lượng Subtask vai trò tự động sinh (<code>TaskCatalog</code>)</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:left;"><strong><code>CONTENT_POST</code></strong></td><td style="text-align:left;"><code>POST</code></td><td style="text-align:center;"><code>&quot;bài&quot;</code></td><td style="text-align:left;">5 vai trò (<code>POST_RESEARCH</code>, <code>POST_CONTENT</code>, <code>POST_MEDIA</code>, <code>POST_EDITING</code>, <code>POST_PUBLISHING</code>)</td></tr><tr><td style="text-align:center;">2</td><td style="text-align:left;"><strong><code>SHORT_VIDEO</code></strong></td><td style="text-align:left;"><code>SHORT_VIDEO</code></td><td style="text-align:center;"><code>&quot;video&quot;</code></td><td style="text-align:left;">4 vai trò (<code>VIDEO_SCRIPT</code>, <code>VIDEO_SHOOT</code>, <code>VIDEO_EDIT</code>, <code>VIDEO_PUBLISH</code>)</td></tr><tr><td style="text-align:center;">3</td><td style="text-align:left;"><strong><code>SURVEY</code></strong></td><td style="text-align:left;"><code>SURVEY</code></td><td style="text-align:center;"><code>&quot;khảo sát&quot;</code></td><td style="text-align:left;">3 vai trò (<code>SURVEY_DESIGN</code>, <code>SURVEY_DISTRIBUTE</code>, <code>SURVEY_ANALYSIS</code>)</td></tr><tr><td style="text-align:center;">4</td><td style="text-align:left;"><strong><code>EVENT_PLAN</code></strong></td><td style="text-align:left;"><code>EVENT_PLAN</code></td><td style="text-align:center;"><code>&quot;sự kiện&quot;</code></td><td style="text-align:left;">5 vai trò (<code>EVENT_AGENDA</code>, <code>EVENT_LOGISTICS</code>, <code>EVENT_PROMOTION</code>, <code>EVENT_ONSITE</code>, <code>EVENT_REPORT</code>)</td></tr><tr><td style="text-align:center;">5</td><td style="text-align:left;"><strong><code>PRESS_RECOMMENDATION</code></strong></td><td style="text-align:left;"><code>PRESS_RECOMMENDATION</code></td><td style="text-align:center;"><code>&quot;thông cáo&quot;</code></td><td style="text-align:left;">4 vai trò (<code>PRESS_MEDIA_LIST</code>, <code>PRESS_RELEASE</code>, <code>PRESS_PITCHING</code>, <code>PRESS_TRACKING</code>)</td></tr><tr><td style="text-align:center;">6</td><td style="text-align:left;"><strong><code>KOL_BOOKING</code></strong></td><td style="text-align:left;"><code>KOL_BOOKING</code></td><td style="text-align:center;"><code>&quot;KOL&quot;</code></td><td style="text-align:left;">5 vai trò (<code>KOL_SOURCING</code>, <code>KOL_NEGOTIATION</code>, <code>KOL_BRIEF</code>, <code>KOL_CONTENT_REVIEW</code>, <code>KOL_TRACKING</code>)</td></tr><tr><td style="text-align:center;">7</td><td style="text-align:left;"><strong><code>WORKSHOP_SUPPORT</code></strong></td><td style="text-align:left;"><code>WORKSHOP</code></td><td style="text-align:center;"><code>&quot;buổi&quot;</code></td><td style="text-align:left;">5 vai trò (<code>WORKSHOP_PROGRAM</code>, <code>WORKSHOP_SPEAKER</code>, <code>WORKSHOP_LOGISTICS</code>, <code>WORKSHOP_REGISTRATION</code>, <code>WORKSHOP_REPORT</code>)</td></tr><tr><td style="text-align:center;">8</td><td style="text-align:left;"><strong><code>EMAIL_NEWSLETTER</code></strong></td><td style="text-align:left;"><code>EMAIL_NEWSLETTER</code></td><td style="text-align:center;"><code>&quot;bản tin&quot;</code></td><td style="text-align:left;">4 vai trò (<code>EMAIL_CONTENT</code>, <code>EMAIL_DESIGN</code>, <code>EMAIL_SEND</code>, <code>EMAIL_REPORT</code>)</td></tr></tbody></table><p>&gt; <strong>Lưu ý tuân thủ <code>AGENTS.md</code></strong>: Hạng mục <code>LIVESTREAM</code> đã bị loại bỏ hoàn toàn khỏi phạm vi dự án.</p><hr><h2 id="_3-đac-ta-luong-goi-dich-vu-chien-dich-theo-2-che-đo-agency-vs-personal" tabindex="-1">3. Đặc tả Luồng Gói Dịch vụ &amp; Chiến dịch theo 2 Chế độ (<code>AGENCY</code> vs <code>PERSONAL</code>) <a class="header-anchor" href="#_3-đac-ta-luong-goi-dich-vu-chien-dich-theo-2-che-đo-agency-vs-personal" aria-label="Permalink to &quot;3. Đặc tả Luồng Gói Dịch vụ &amp; Chiến dịch theo 2 Chế độ (`AGENCY` vs `PERSONAL`)&quot;">​</a></h2><h3 id="_3-1-trong-che-đo-agency-workspacemode-agency" tabindex="-1">3.1. Trong Chế độ <code>AGENCY</code> (<code>workspaceMode = &quot;AGENCY&quot;</code>) <a class="header-anchor" href="#_3-1-trong-che-đo-agency-workspacemode-agency" aria-label="Permalink to &quot;3.1. Trong Chế độ `AGENCY` (`workspaceMode = &quot;AGENCY&quot;`)&quot;">​</a></h3><ol><li><strong>Giai đoạn 1 — Chốt Gói Truyền thông (<code>3.5.1</code> – <code>3.5.4</code>)</strong>: <ul><li><code>Owner</code> thiết lập danh mục Gói truyền thông mẫu (<code>MediaPackage</code>) tại cấp Agency (<code>3.5.1</code>).</li><li>Tại Workspace của khách hàng, <code>Manager</code> (hoặc <code>Client</code> đề xuất) chọn gói mẫu hoặc tùy chỉnh thành <code>WorkspaceMediaPackage</code> (<code>3.5.3</code>).</li><li>Hỗ trợ xuất bảng báo giá/đề xuất gói ra file <strong>PDF đa ngôn ngữ</strong> (<code>PackageExportRenderer</code>) hoặc tạo link chia sẻ công khai (<code>/s/:token</code>) gửi cho khách hàng xem trước.</li><li>Sau khi thống nhất với khách hàng, <code>Owner</code>/<code>Manager</code> bấm xác nhận chốt gói (<code>3.5.4 Approve Media Package</code> → <code>status = APPROVED</code>), mở khóa bước 2 trên thanh Tiến trình Sidebar.</li></ul></li><li><strong>Giai đoạn 2 — Lập &amp; Triển khai Chiến dịch (<code>3.5.5</code> – <code>3.5.9</code>)</strong>: <ul><li><code>Manager</code> tạo bản nháp Chiến dịch (<code>3.5.5</code>), nhập mục tiêu, ý tưởng và lên danh sách các hạng mục công việc (<code>CampaignWorkItem</code>).</li><li><code>CampaignPlanValidator</code> kiểm tra tổng số lượng từng loại hạng mục không vượt quá hạn mức của <code>WorkspaceMediaPackage</code> đã chốt.</li><li>Khi <code>Manager</code> bấm <strong>Chốt &amp; Triển khai Chiến dịch (<code>3.5.8</code> / <code>deploy</code>)</strong>: <ul><li>Chiến dịch chuyển sang <code>ACTIVE</code>.</li><li><code>CampaignTaskStore.draftTask</code> tự động sinh các <code>TaskDocument</code> cha trong MongoDB, đồng thời <strong>sinh sẵn bộ Subtask theo vai trò chuẩn (<code>TaskCatalog</code>)</strong> cho từng Task (mặc định <code>status = TODO</code>, <code>dueDate</code> = hạn của Task cha, chờ <code>Manager</code> gán người phụ trách).</li></ul></li><li>Trong suốt chiến dịch, tất cả các bên theo dõi tiến độ trên <code>CampaignTimelineGrid</code> (<code>3.5.6</code>), nơi hiển thị trực quan từng Task, các Subtask con, cờ <strong>Trễ hạn (<code>Overdue</code>)</strong> và cờ <strong>Chờ Client duyệt (<code>Awaiting Client</code>)</strong>.</li></ul></li></ol><h3 id="_3-2-trong-che-đo-personal-workspacemode-personal" tabindex="-1">3.2. Trong Chế độ <code>PERSONAL</code> (<code>workspaceMode = &quot;PERSONAL&quot;</code>) <a class="header-anchor" href="#_3-2-trong-che-đo-personal-workspacemode-personal" aria-label="Permalink to &quot;3.2. Trong Chế độ `PERSONAL` (`workspaceMode = &quot;PERSONAL&quot;`)&quot;">​</a></h3><p>Khi người dùng làm việc trong Không gian Cá nhân hoặc Nhóm bài tập (<code>workspaceMode = &quot;PERSONAL&quot;</code>):</p><ol><li><strong>Không bắt buộc Gói dịch vụ (<code>Package-less Workflow</code>)</strong>: <ul><li>Bước <code>1. Gói dịch vụ</code> được ẩn khỏi thanh Tiến trình Sidebar.</li><li>Nếu người dùng vào trang <strong>Chiến dịch (<code>/workspaces/:id/campaigns</code>)</strong> để lập kế hoạch dài hạn (<code>3.5.5</code> – <code>3.5.8</code>), Backend tự động khởi tạo ngầm một <code>WorkspaceMediaPackage</code> khung nội bộ không giới hạn trần số lượng, cho phép người dùng cá nhân tự do thêm bất kỳ số lượng hạng mục nào trong 8 loại <code>TaskType</code> và bấm <code>Deploy</code> ngay lập tức.</li><li>Mọi Task sinh ra từ chiến dịch cá nhân mặc định có <code>requiresClientApproval = false</code> và tự gán cho chủ không gian nếu chưa chọn người khác.</li></ul></li><li><strong>Làm việc không cần Chiến dịch (<code>Standalone Task Bypass</code>)</strong>: <ul><li>Người dùng cá nhân thậm chí không cần vào trang Chiến dịch mà có thể bấm <strong>&quot;+ Tạo công việc mới&quot;</strong> ngay tại trang Công việc (<code>/workspaces/:id/tasks</code>) hoặc từ <strong>Bệ phóng Sáng tạo Cá nhân (<code>Personal Quick Launchpad</code>)</strong> trên Dashboard để tạo trực tiếp 1 công việc lẻ (hệ thống tự gắn vào chiến dịch cá nhân mặc định chạy ngầm).</li></ul></li></ol><hr><h2 id="_4-đac-ta-luong-yeu-cau-noi-dung-cua-khach-hang-3-5-10-–-3-5-13" tabindex="-1">4. Đặc tả Luồng Yêu cầu Nội dung của Khách hàng (<code>3.5.10</code> – <code>3.5.13</code>) <a class="header-anchor" href="#_4-đac-ta-luong-yeu-cau-noi-dung-cua-khach-hang-3-5-10-–-3-5-13" aria-label="Permalink to &quot;4. Đặc tả Luồng Yêu cầu Nội dung của Khách hàng (`3.5.10` – `3.5.13`)&quot;">​</a></h2><p>Luồng <code>Content Request</code> phục vụ riêng cho tương tác giữa <code>Client</code> và <code>Manager</code> trong các Workspace có <code>workspaceMode = &quot;AGENCY&quot;</code>:</p><ol><li><strong><code>3.5.10 Create Content Request</code> (<code>Client</code>)</strong>: <ul><li>Từ <code>Client Portal</code> (<code>/workspaces/:id/portal</code>), <code>Client</code> gửi yêu cầu làm thêm hoặc điều chỉnh nội dung (nhập tiêu đề, loại nội dung mong muốn, mô tả yêu cầu, hạn mong muốn và tệp đính kèm). Bản ghi mới có <code>status = PENDING</code>.</li></ul></li><li><strong><code>3.5.11 Track Request Status</code> (<code>Manager</code>, <code>Client</code>)</strong>: <ul><li>Cả <code>Client</code> và <code>Manager</code> xem danh sách và trạng thái thời gian thực của từng yêu cầu, kèm liên kết tới <code>Task</code> thực thi sau khi yêu cầu được duyệt.</li></ul></li><li><strong><code>3.5.12 Update Request</code> (<code>Manager</code>, <code>Client</code>)</strong>: <ul><li>Khi yêu cầu đang ở <code>PENDING</code>, <code>Client</code> có thể sửa nội dung mô tả; <code>Manager</code> có thể bấm <strong>Chấp nhận</strong> (tự động chuyển hóa yêu cầu thành một <code>TaskDocument</code> trong Workspace để giao cho <code>Creator</code>) hoặc <strong>Từ chối</strong> kèm ghi chú phản hồi.</li></ul></li><li><strong><code>3.5.13 Cancel Request</code> (<code>Client</code>)</strong>: <ul><li>Khi yêu cầu đang ở <code>PENDING</code>, <code>Client</code> có quyền rút lại / hủy yêu cầu (<code>status = CANCELLED</code>).</li></ul></li></ol><ul><li><strong>Hành vi ở chế độ <code>PERSONAL</code></strong>: Vì không có <code>Client</code>, mục <code>Yêu cầu Nội dung (/requests)</code> được ẩn khỏi Sidebar để tránh dư thừa; người dùng cá nhân tạo trực tiếp Task tại <code>/tasks</code>.</li></ul>',22)])])}const y=e(n,[["render",a]]);export{u as __pageData,y as default};
